const updateIssue = `-- name: UpdateIssue :one
WITH candidate AS (
    SELECT
        i.id, i.workspace_id, i.title, i.description, i.status, i.priority, i.executor_type, i.executor_id, i.creator_type, i.creator_id, i.parent_issue_id, i.acceptance_criteria, i.context_refs, i.position, i.due_date, i.created_at, i.updated_at, i.number, i.project_id, i.origin_type, i.origin_id, i.first_executed_at, i.start_date, i.metadata, i.stage, i.properties, i.revision, i.last_activity_at, i.owner_type, i.owner_id, i.reviewer_type, i.reviewer_id, i.executor_generation,
        COALESCE($3::text, i.title) AS next_title,
        COALESCE($4::text, i.description) AS next_description,
        COALESCE($5::text, i.status) AS next_status,
        COALESCE($6::text, i.priority) AS next_priority,
        $7::text AS next_executor_type,
        $8::uuid AS next_executor_id,
        $9::text AS next_owner_type,
        $10::uuid AS next_owner_id,
        $11::text AS next_reviewer_type,
        $12::uuid AS next_reviewer_id,
        CASE
            -- An explicit position wins. Cross-column drag-and-drop sends
            -- status and position together and means the slot it dropped on.
            WHEN $13::double precision IS NOT NULL
                THEN $13::double precision
            -- position ranks an issue *within* its (workspace, status)
            -- column, so it stops meaning anything the moment the column
            -- changes: the value that put the issue on top of Todo lands it
            -- below every hand-dragged issue in Done. Re-rank to the top of
            -- the destination, the same policy new issues get from
            -- NextTopPosition. Keep the two in sync.
            --
            -- Two status changes running at once can read the same MIN and
            -- claim one slot. Every position-ordered query carries a unique
            -- final key (created_at DESC, id DESC), so a tie leaves the
            -- relative order of simultaneous moves arbitrary but never
            -- unstable across pages. Creation avoids the tie by computing its
            -- min under the workspace counter lock; a status change holds no
            -- such lock and is not worth taking one for.
            WHEN i.status IS DISTINCT FROM COALESCE($5::text, i.status)
                THEN (
                    SELECT COALESCE(MIN(target.position), 0) - 1
                    FROM issue AS target
                    WHERE target.workspace_id = i.workspace_id
                      AND target.status = $5::text
                )
            ELSE i.position
        END AS next_position,
        $14::date AS next_start_date,
        $15::date AS next_due_date,
        $16::uuid AS next_parent_issue_id,
        $17::uuid AS next_project_id,
        $18::integer AS next_stage
    FROM issue AS i
    WHERE i.id = $1
      AND ($2::bigint IS NULL OR i.revision = $2::bigint)
), changed AS (
    SELECT
        candidate.id, candidate.workspace_id, candidate.title, candidate.description, candidate.status, candidate.priority, candidate.executor_type, candidate.executor_id, candidate.creator_type, candidate.creator_id, candidate.parent_issue_id, candidate.acceptance_criteria, candidate.context_refs, candidate.position, candidate.due_date, candidate.created_at, candidate.updated_at, candidate.number, candidate.project_id, candidate.origin_type, candidate.origin_id, candidate.first_executed_at, candidate.start_date, candidate.metadata, candidate.stage, candidate.properties, candidate.revision, candidate.last_activity_at, candidate.owner_type, candidate.owner_id, candidate.reviewer_type, candidate.reviewer_id, candidate.executor_generation, candidate.next_title, candidate.next_description, candidate.next_status, candidate.next_priority, candidate.next_executor_type, candidate.next_executor_id, candidate.next_owner_type, candidate.next_owner_id, candidate.next_reviewer_type, candidate.next_reviewer_id, candidate.next_position, candidate.next_start_date, candidate.next_due_date, candidate.next_parent_issue_id, candidate.next_project_id, candidate.next_stage,
        ROW(
            title, description, status, priority, executor_type, executor_id,
            owner_type, owner_id, reviewer_type, reviewer_id,
            position, start_date, due_date, parent_issue_id, project_id, stage
        ) IS DISTINCT FROM ROW(
            next_title, next_description, next_status, next_priority,
            next_executor_type, next_executor_id, next_owner_type, next_owner_id,
            next_reviewer_type, next_reviewer_id, next_position, next_start_date,
            next_due_date, next_parent_issue_id, next_project_id, next_stage
        ) AS did_change,
        ROW(
            title, description, status, priority, executor_type, executor_id,
            owner_type, owner_id, reviewer_type, reviewer_id,
            start_date, due_date, parent_issue_id, project_id, stage
        ) IS DISTINCT FROM ROW(
            next_title, next_description, next_status, next_priority,
            next_executor_type, next_executor_id, next_owner_type, next_owner_id,
            next_reviewer_type, next_reviewer_id, next_start_date, next_due_date,
            next_parent_issue_id, next_project_id, next_stage
        ) AS did_activity
    FROM candidate
)
UPDATE issue AS i SET
    title = changed.next_title,
    description = changed.next_description,
    status = changed.next_status,
    priority = changed.next_priority,
    executor_type = changed.next_executor_type,
    executor_id = changed.next_executor_id,
    owner_type = changed.next_owner_type,
    owner_id = changed.next_owner_id,
    reviewer_type = changed.next_reviewer_type,
    reviewer_id = changed.next_reviewer_id,
    position = changed.next_position,
    start_date = changed.next_start_date,
    due_date = changed.next_due_date,
    parent_issue_id = changed.next_parent_issue_id,
    project_id = changed.next_project_id,
    stage = changed.next_stage,
    revision = i.revision + changed.did_change::integer,
    last_activity_at = CASE WHEN changed.did_activity
        THEN GREATEST(COALESCE(i.last_activity_at, i.updated_at), now())
        ELSE i.last_activity_at
    END,
    updated_at = CASE WHEN changed.did_change THEN now() ELSE i.updated_at END
FROM changed
WHERE i.id = changed.id
  -- Re-check the precondition on the row version that UPDATE actually locks.
  -- Under READ COMMITTED, concurrent statements may both populate candidate
  -- from the same snapshot; EvalPlanQual re-evaluates this target-row predicate
  -- after waiting for the first writer, leaving the stale writer with 0 rows.
  AND ($2::bigint IS NULL OR i.revision = $2::bigint)
RETURNING i.id, i.workspace_id, i.title, i.description, i.status, i.priority, i.executor_type, i.executor_id, i.creator_type, i.creator_id, i.parent_issue_id, i.acceptance_criteria, i.context_refs, i.position, i.due_date, i.created_at, i.updated_at, i.number, i.project_id, i.origin_type, i.origin_id, i.first_executed_at, i.start_date, i.metadata, i.stage, i.properties, i.revision, i.last_activity_at, i.owner_type, i.owner_id, i.reviewer_type, i.reviewer_id, i.executor_generation
`

